style.css:
/* Animekais Blue Theme */

/* General background and text */
body {
  background-color: #0d1b2a; /* deep navy blue */
  color: #e0eaff; /* light bluish text */
  font-family: 'Segoe UI', Arial, sans-serif;
}

/* Header */
header {
  background-color: #1b263b; /* darker blue */
  color: #ffffff;
  padding: 1rem;
  text-align: center;
}

/* Navigation bar */
nav {
  background-color: #274c77; /* medium blue */
  padding: 0.5rem;
}

nav a {
  color: #e0eaff;
  text-decoration: none;
  margin: 0 1rem;
}

nav a:hover {
  color: #a3cef1; /* lighter blue on hover */
}

/* Main content */
main {
  background-color: #1e3a5f; /* rich blue tone */
  padding: 2rem;
  border-radius: 8px;
}

/* Buttons */
button {
  background-color: #3a86ff; /* bright blue */
  color: #ffffff;
  border: none;
  padding: 0.6rem 1.2rem;
  border-radius: 4px;
  cursor: pointer;
}

button:hover {
  background-color: #2f70d6; /* darker hover */
}

/* Footer */
footer {
  background-color: #1b263b;
  color: #a3cef1;
  text-align: center;
  padding: 1rem;
  margin-top: 2rem;
}
